export type CoverageStatus = 'proven' | 'bounded' | 'refused' | 'not-admitted';
export type CoverageProvenance = 'sealed-receipts' | 'run-record';

export interface CoverageApplicationRow {
	readonly id: string;
	readonly application: string;
