 * is refused rather than published with an identifier nothing backs.
 */
function runLicence(stages: unknown): CoverageRunRecord['licence'] {
	if (!Array.isArray(stages)) return undefined;
	const stage = stages.find(
		(entry) =>
			typeof entry === 'object' &&
