): Promise<InterventionRecordReading | null> {
	for (const file of INTERVENTION_RECORD_FILES) {
		let body: string;
		try {
			body = await readFile(path.join(directory, file), 'utf8');
		} catch {
			continue;
		}
		let parsed: unknown;
		try {
			parsed = JSON.parse(body);
		} catch {
			continue;
